class Solution {
public:
    int sumOfPower(vector<int>& nums, int k) {
        long long MOD = 1e9 + 7;
        vector<long long> dp(k + 1, 0);
        dp[0] = 1;
        for (int x : nums) {
            for (int s = k; s >= 0; --s) {
                long long inc = (s >= x) ? dp[s - x] : 0;
                dp[s] = (dp[s] * 2 + inc) % MOD;
            }
        }
        return dp[k];
    }
};

class Solution {
    public int sumOfPower(int[] nums, int k) {
        long MOD = 1_000_000_007L;
        long[] dp = new long[k + 1];
        dp[0] = 1;
        for (int x : nums) {
            for (int s = k; s >= 0; s--) {
                long inc = (s >= x) ? dp[s - x] : 0;
                dp[s] = (dp[s] * 2 + inc) % MOD;
            }
        }
        return (int) dp[k];
    }
}

var sumOfPower = function(nums, k) {
    const MOD = 1000000007n;
    const dp = new Array(k + 1).fill(0n);
    dp[0] = 1n;
    for (const x of nums) {
        for (let s = k; s >= 0; --s) {
            const inc = (s >= x) ? dp[s - x] : 0n;
            dp[s] = (dp[s] * 2n + inc) % MOD;
        }
    }
    return Number(dp[k]);
};
